    if (wrapRE.test(modeStr)) {
      modeStr = wrapRE.exec(modeStr)[1]
    }

    if (!modeStr) {
      return
    }

    const conditionMap = new Map()
    modeStr.split('|').forEach(item => {
      const arr = item.split(':')
      const key = arr[0] || 'noMode'
      conditionMap.set(key, arr.slice(1))
